  classDef process fill:#3b82f6,stroke:#333,stroke-width:2px,color:#fff
  classDef decision fill:#8b5cf6,stroke:#333,stroke-width:2px,color:#fff
  classDef endpoint fill:#1e293b,stroke:#333,stroke-width:2px,color:#fff
